#!/usr/bin/env python3
"""Payroll summary from clock exports. Usage: payroll.py INPUT_DIR OUTPUT_FILE"""
import csv
import json
import sys
from datetime import datetime, timedelta, timezone
from decimal import Decimal
from fractions import Fraction
from pathlib import Path
from zoneinfo import ZoneInfo

UTC = timezone.utc
EPOCH = datetime(1970, 1, 1, tzinfo=UTC)


def read_text(path):
    return Path(path).read_text(encoding="utf-8-sig")


def csv_rows(path, **kw):
    text = read_text(path)
    rows = csv.DictReader(text.splitlines(), **kw)
    for r in rows:
        r = {(k or "").strip(): (v or "").strip() for k, v in r.items() if k is not None}
        if any(r.values()):
            yield r


def to_utc(dt):
    return int((dt - EPOCH).total_seconds())


def local_to_ts(naive, tz, dst_flag=None):
    """Instant (epoch seconds) of a local wall time. dst_flag picks the repeated hour's occurrence;
    None means the first (daylight saving) occurrence."""
    a = naive.replace(tzinfo=tz, fold=0)
    b = naive.replace(tzinfo=tz, fold=1)
    if a.utcoffset() != b.utcoffset():
        if dst_flag is None:
            dt = a
        else:
            dt = a if bool(a.dst()) == dst_flag else b
    else:
        dt = a
    return to_utc(dt)


def parse_iso(s):
    s = s.strip()
    if s.endswith("Z") or s.endswith("z"):
        s = s[:-1] + "+00:00"
    return datetime.fromisoformat(s)


def read_site(site, tzname, fmt, d):
    tz = ZoneInfo(tzname)
    out = []  # (id, emp, dir, ts)
    files = sorted(p for p in d.rglob("*") if p.is_file()) if d.is_dir() else []
    for f in files:
        if fmt == "abbr-csv":
            for r in csv_rows(f):
                dt = datetime.strptime(r["Date"] + " " + r["Time"].upper(), "%m/%d/%Y %I:%M:%S %p")
                z = r.get("Zone", "").upper()
                flag = True if z.endswith("DT") else False if z.endswith("ST") else None
                out.append((r["Record"], r["Badge"], r["Punch"].upper(), local_to_ts(dt, tz, flag)))
        elif fmt == "epoch-jsonl":
            for line in read_text(f).splitlines():
                line = line.strip()
                if not line:
                    continue
                o = json.loads(line)
                if o.get("heartbeat"):
                    continue
                if "ts_ms" in o:
                    ts = int(o["ts_ms"]) // 1000
                elif "ts" in o:
                    ts = int(o["ts"])
                else:
                    continue
                out.append((str(o["id"]), o["emp"], o["dir"].upper(), ts))
        elif fmt == "offset-csv":
            for r in csv_rows(f, delimiter=";"):
                ts = to_utc(parse_iso(r["timestamp"]))
                out.append((r["punch_id"], r["employee"],
                            "IN" if r["event"] == "clock_in" else "OUT", ts))
        elif fmt == "legacy-fixed":
            for line in read_text(f).split("\n"):
                line = line.rstrip("\r")
                if not line.startswith("D"):
                    continue
                pid = line[1:9]
                badge = line[9:15].strip()
                emp = "E" + badge
                dr = "IN" if line[15] == "I" else "OUT"
                dt = datetime.strptime(line[16:30], "%Y%m%d%H%M%S")
                probe = dt.replace(tzinfo=tz)
                std = probe.utcoffset() - (probe.dst() or timedelta(0))
                ts = to_utc((dt - std).replace(tzinfo=UTC))
                out.append((pid, emp, dr, ts))
        elif fmt == "de-tsv":
            for r in csv_rows(f, delimiter="\t"):
                dt = datetime.strptime(r["Datum"] + " " + r["Uhrzeit"], "%d.%m.%Y %H:%M")
                flag = True if r["Zeitzone"].upper() == "MESZ" else False
                out.append((r["Nr"], r["Ausweis"], "IN" if r["Buchung"].upper() == "K" else "OUT",
                            local_to_ts(dt, tz, flag)))
        elif fmt == "local-csv":
            for r in csv_rows(f):
                dt = datetime.strptime(r["local_time"], "%Y-%m-%d %H:%M:%S")
                out.append((r["punch_ref"], r["employee_id"], r["direction"].upper(),
                            local_to_ts(dt, tz)))
        elif fmt == "local-jsonl":
            for line in read_text(f).splitlines():
                line = line.strip()
                if not line:
                    continue
                p = json.loads(line).get("punch")
                if not p:
                    continue
                dt = datetime.strptime(p["at"], "%Y-%m-%d %H:%M:%S")
                out.append((str(p["id"]), p["badge"], p["type"].upper(), local_to_ts(dt, tz)))
        else:
            raise ValueError("unknown format " + fmt)
    return out


def main(inp, outfile):
    inp = Path(inp)
    period = json.loads(read_text(inp / "period.json"))
    pstart = datetime.strptime(period["start"], "%Y-%m-%d").date()
    pend = datetime.strptime(period["end"], "%Y-%m-%d").date()
    cutoff = to_utc(parse_iso(period["corrections_cutoff"]))

    sites = {r["site"]: r for r in csv_rows(inp / "sites.csv")}
    zones = {s: ZoneInfo(r["timezone"]) for s, r in sites.items()}
    employees = {}
    for r in csv_rows(inp / "employees.csv"):
        employees[r["employee_id"]] = r["home_site"]
    rates = {}
    for r in csv_rows(inp / "rates.csv"):
        rates.setdefault(r["employee_id"], []).append(
            (r["effective_from"], Decimal(r["hourly_rate"])))
    for v in rates.values():
        v.sort(key=lambda x: x[0])  # stable: later rows win on equal dates

    # 1. collect
    punches = {}  # (site, id) -> [emp, dir, ts]
    ever = set()
    for site, r in sites.items():
        for pid, emp, dr, ts in read_site(site, r["timezone"], r["format"], inp / "exports" / site):
            key = (site, pid)
            ever.add(key)
            if key not in punches:
                punches[key] = [emp, dr, ts]

    # 2. corrections
    corrs = []
    cdir = inp / "corrections"
    if cdir.is_dir():
        for f in sorted(cdir.rglob("*")):
            if f.is_file():
                corrs.extend(csv_rows(f))
    corrs = [(to_utc(parse_iso(c["issued_at"])), c) for c in corrs]
    corrs = [x for x in corrs if x[0] <= cutoff]
    corrs.sort(key=lambda x: (x[0], x[1]["correction_id"]))
    applied = 0
    for _, c in corrs:
        key = (c["site"], c["punch_id"])
        act = c["action"].lower()
        if act == "void":
            if key in punches:
                del punches[key]
                applied += 1
        elif act == "set":
            if key in punches:
                punches[key][2] = to_utc(parse_iso(c["time"]))
                applied += 1
        elif act == "add":
            if key not in ever:
                ever.add(key)
                punches[key] = [c["employee"], c["type"].upper(), to_utc(parse_iso(c["time"]))]
                applied += 1

    by_emp = {}
    for (site, pid), (emp, dr, ts) in punches.items():
        if emp in employees:
            by_emp.setdefault(emp, []).append((ts, 0 if dr == "OUT" else 1, site, pid, dr))

    off_cache = {}

    def offset(site, ts):
        k = (site, ts // 900)
        v = off_cache.get(k)
        if v is None:
            v = int(zones[site].utcoffset(datetime.fromtimestamp(ts, UTC).astimezone(zones[site])).total_seconds()) \
                if False else int(datetime.fromtimestamp(ts, zones[site]).utcoffset().total_seconds())
            off_cache[k] = v
        return v

    def rnd(site, ts):
        off = offset(site, ts)
        s = (ts + off) % 3600
        m = (s + 180) // 360 * 360
        return ts + (m - s)

    def workday(emp, rts):
        return datetime.fromtimestamp(rts, zones[employees[emp]]).date()

    def inperiod(d):
        return pstart <= d <= pend

    exc = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0, corrections_applied=applied)
    shifts = {e: [] for e in employees}  # (in_r, out_r, site, workday)

    for emp, lst in by_emp.items():
        lst.sort()
        kept = []
        last = None
        for ts, _, site, pid, dr in lst:
            if last is not None and last[4] == dr and ts - last[0] <= 300:
                if inperiod(workday(emp, rnd(site, ts))):
                    exc["duplicates_dropped"] += 1
                continue
            last = (ts, 0, site, pid, dr)
            kept.append(last)
        cur = None  # (rounded, site)
        for ts, _, site, pid, dr in kept:
            r = rnd(site, ts)
            if dr == "IN":
                if cur is not None:
                    if inperiod(workday(emp, cur[0])):
                        exc["open_shifts"] += 1
                cur = (r, site)
            else:
                if cur is not None and r - cur[0] <= 16 * 3600:
                    shifts[emp].append((cur[0], r, cur[1], workday(emp, cur[0])))
                    cur = None
                else:
                    if cur is not None:
                        if inperiod(workday(emp, cur[0])):
                            exc["open_shifts"] += 1
                        cur = None
                    if inperiod(workday(emp, r)):
                        exc["orphan_outs"] += 1
        if cur is not None and inperiod(workday(emp, cur[0])):
            exc["open_shifts"] += 1

    def night_minutes(site, a, b):
        n = 0
        for t in range(a, b, 60):
            h = ((t + offset(site, t)) % 86400) // 3600
            if h >= 22 or h < 6:
                n += 1
        return n

    result = {}
    for emp in employees:
        sh = sorted(s for s in shifts[emp] if inperiod(s[3]))
        cnt = paid_t = ot_t = night_t = 0
        gross = Fraction(0)
        day_cum = {}
        week_cum = {}
        for a, b, site, wd in sh:
            worked = max(0, (b - a) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = min(night_minutes(site, a, b), paid)
            before = day_cum.get(wd, 0)
            day_cum[wd] = before + paid
            dot = max(0, before + paid - 480) - max(0, before - 480)
            wk = wd - timedelta(days=wd.weekday())
            nd = paid - dot
            wb = week_cum.get(wk, 0)
            week_cum[wk] = wb + nd
            wot = max(0, wb + nd - 2400) - max(0, wb - 2400)
            ot = dot + wot
            reg = paid - ot
            rate = None
            for eff, rt in rates.get(emp, []):
                if eff <= wd.isoformat():
                    rate = rt
            if rate is None and rates.get(emp):
                rate = rates[emp][0][1]
            rate = Fraction(rate or 0)
            gross += rate * (Fraction(reg) + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * night / 60
            cnt += 1
            paid_t += paid
            ot_t += ot
            night_t += night
        cents = int((gross * 100 + Fraction(1, 2)) // 1)
        result[emp] = dict(shifts=cnt, paid_minutes=paid_t, overtime_minutes=ot_t,
                           night_minutes=night_t, gross=cents)

    def money(c):
        return "%d.%02d" % divmod(c, 100)

    totals = {k: sum(v[k] for v in result.values())
              for k in ("shifts", "paid_minutes", "overtime_minutes", "night_minutes", "gross")}
    totals["gross"] = money(totals["gross"])
    for v in result.values():
        v["gross"] = money(v["gross"])
    out = {"period": {"start": period["start"], "end": period["end"]},
           "employees": result, "exceptions": exc, "totals": totals}
    Path(outfile).parent.mkdir(parents=True, exist_ok=True)
    Path(outfile).write_text(json.dumps(out, indent=1))


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
